namespace simp {
namespace {

bool containsReturn(const Statement& statement) {
    if (statement.kind == StatementKind::Return) return true;
    for (const auto& child : statement.body) {
        if (containsReturn(child)) return true;
    }
    for (const auto& child : statement.alternate) {
        if (containsReturn(child)) return true;
    }
    for (const auto& handler : statement.exceptionHandlers) {
        for (const auto& child : handler.body) {
            if (containsReturn(child)) return true;
        }
    }
    for (const auto& child : statement.cleanup) {
        if (containsReturn(child)) return true;
    }
    return false;
}

bool containsSuperCall(const Statement& statement) {
    if (statement.kind == StatementKind::SuperConstructorCall) return true;
    for (const auto& child : statement.body) {
        if (containsSuperCall(child)) return true;
    }
    for (const auto& child : statement.alternate) {
        if (containsSuperCall(child)) return true;
    }
    for (const auto& handler : statement.exceptionHandlers) {
        for (const auto& child : handler.body) {
            if (containsSuperCall(child)) return true;
        }
    }
    for (const auto& child : statement.cleanup) {
        if (containsSuperCall(child)) return true;
    }
    return false;
}

} // namespace

std::string SemanticAnalyzer::qualify(const std::vector<std::string>& path,
                                      const std::string& name) const {
    std::string result;
    for (const auto& component : path) {
        if (!result.empty()) result += ".";
        result += component;
    }
    if (!name.empty()) {
        if (!result.empty()) result += ".";
        result += name;
    }
    return result;
}

const std::unordered_map<std::string, SemanticAnalyzer::ImportBinding>&
SemanticAnalyzer::activeImports() const {
    static const std::unordered_map<std::string, ImportBinding> empty;
    const auto found = importAliases_.find(currentModule_);
    return found == importAliases_.end() ? empty : found->second;
}

bool SemanticAnalyzer::hasNamespaceOrClass(
    const std::string& name, const std::vector<std::string>& namespacePath) const {
    const auto visible = [this](const std::string& candidate) {
        const auto classFound = classes_.find(candidate);
        if (classFound != classes_.end()) {
            return classFound->second->builtin ||
                   classFound->second->moduleName == currentModule_;
        }
        const auto namespaceFound = namespaceOwners_.find(candidate);
        return namespaceFound != namespaceOwners_.end() &&
               namespaceFound->second == currentModule_;
    };
    for (std::size_t depth = namespacePath.size() + 1; depth > 0; --depth) {
        const auto prefixLength = depth - 1;
        const std::vector<std::string> prefix(
            namespacePath.begin(),
            namespacePath.begin() + static_cast<std::ptrdiff_t>(prefixLength));
        const auto candidate = qualify(prefix, name);
        if (visible(candidate)) {
            return true;
        }
        if (prefixLength == 0 && activeImports().find(name) != activeImports().end()) {
            return true;
        }
    }
    return false;
}

std::string SemanticAnalyzer::resolveClassName(
    const std::string& name, const std::vector<std::string>& namespacePath,
    const SourceLocation& location) const {
    std::vector<std::string> components;
    std::size_t begin = 0;
    while (begin < name.size()) {
        const auto end = name.find('.', begin);
        components.push_back(name.substr(
            begin, end == std::string::npos ? std::string::npos : end - begin));
        begin = end == std::string::npos ? name.size() : end + 1;
    }
    if (components.empty()) {
        throw DiagnosticError(location, "unknown class '" + name + "'");
    }

    std::string candidate;
    std::string resolvedOwner = currentModule_;
    bool firstFound = false;
    const auto visible = [this](const std::string& candidate,
                                const std::string& owner) {
        const auto classFound = classes_.find(candidate);
        if (classFound != classes_.end()) {
            return classFound->second->builtin ||
                   classFound->second->moduleName == owner;
        }
        const auto namespaceFound = namespaceOwners_.find(candidate);
        return namespaceFound != namespaceOwners_.end() &&
               namespaceFound->second == owner;
    };
    for (std::size_t depth = namespacePath.size() + 1; depth > 0; --depth) {
        const auto prefixLength = depth - 1;
        const std::vector<std::string> prefix(
            namespacePath.begin(),
            namespacePath.begin() + static_cast<std::ptrdiff_t>(prefixLength));
        candidate = qualify(prefix, components.front());
        if (visible(candidate, currentModule_)) {
            firstFound = true;
            break;
        }
        if (prefixLength == 0) {
            const auto imported = activeImports().find(components.front());
            if (imported != activeImports().end()) {
                candidate = imported->second.qualifiedName;
                resolvedOwner = imported->second.moduleName;
                firstFound = true;
                break;
            }
        }
    }
    if (!firstFound) {
        throw DiagnosticError(location, "unknown class '" + name + "'");
    }
    for (std::size_t index = 1; index < components.size(); ++index) {
        candidate += "." + components[index];
        if (!visible(candidate, resolvedOwner)) {
            throw DiagnosticError(location, "unknown qualified class '" + name + "'");
        }
    }
    const auto found = classes_.find(candidate);
    if (found == classes_.end()) {
        throw DiagnosticError(location, "qualified name '" + name + "' is not a class");
    }
    return candidate;
}

void SemanticAnalyzer::normalizeType(
    std::string& type, const std::vector<std::string>& namespacePath,
    const SourceLocation& location) const {
    if (type == "int" || type == "bool" || type == "float" || type == "unsigned" ||
        type == "string" || type == "array" || type == "map" ||
        type == "buffer" || type == "handle" ||
        type == "any" || type == "type" || type == "void") {
        return;
    }
    if (type.find('.') == std::string::npos &&
        !hasNamespaceOrClass(type, namespacePath)) {
        throw DiagnosticError(location, "unknown type or class '" + type + "'");
    }
    type = resolveClassName(type, namespacePath, location);
}

void SemanticAnalyzer::normalizeExpression(
    Expression& expression, const std::vector<std::string>& namespacePath) {
    if (expression.kind == ExpressionKind::TypeTest &&
        expression.value != "int" && expression.value != "bool" &&
        expression.value != "float" && expression.value != "unsigned" &&
        expression.value != "string" && expression.value != "array" &&
        expression.value != "map" && expression.value != "buffer" &&
        expression.value != "handle" && expression.value != "any" &&
        expression.value != "type" &&
        expression.value != "void") {
        if (expression.value.find('.') == std::string::npos &&
            !hasNamespaceOrClass(expression.value, namespacePath)) {
            throw DiagnosticError(expression.typeLocation,
                                  "unknown type name '" + expression.value + "'");
        }
        expression.value = resolveClassName(expression.value, namespacePath,
                                             expression.typeLocation);
    }
    if (expression.kind == ExpressionKind::TypeName &&
        expression.value != "int" && expression.value != "bool" &&
        expression.value != "float" && expression.value != "unsigned" &&
        expression.value != "string" && expression.value != "array" &&
        expression.value != "map" && expression.value != "buffer" &&
        expression.value != "handle" && expression.value != "any" &&
        expression.value != "type") {
        expression.value = resolveClassName(expression.value, namespacePath,
                                             expression.typeLocation);
    }
    if (expression.left) normalizeExpression(*expression.left, namespacePath);
    if (expression.right) normalizeExpression(*expression.right, namespacePath);
    for (auto& argument : expression.arguments) {
        normalizeExpression(*argument, namespacePath);
    }
}

void SemanticAnalyzer::normalizeStatements(
    std::vector<Statement>& statements, const std::vector<std::string>& namespacePath) {
    for (auto& statement : statements) {
        if (statement.kind == StatementKind::Declaration) {
            normalizeType(statement.declaredType, namespacePath, statement.location);
        }
        if (statement.kind == StatementKind::InlineC) {
            for (auto& capture : statement.inlineCaptures) {
                normalizeType(capture.type, namespacePath, capture.location);
            }
        }
        if (statement.kind == StatementKind::SuperConstructorCall) {
            statement.name = resolveClassName(statement.name, namespacePath,
                                               statement.location);
        }
        for (auto& handler : statement.exceptionHandlers) {
            if (!handler.exceptionType.empty()) {
                handler.exceptionType = resolveClassName(
                    handler.exceptionType, namespacePath, handler.location);
            }
            normalizeStatements(handler.body, namespacePath);
        }
        if (statement.target) normalizeExpression(*statement.target, namespacePath);
        for (auto& expression : statement.expressions) {
            normalizeExpression(*expression, namespacePath);
        }
        normalizeStatements(statement.body, namespacePath);
        normalizeStatements(statement.alternate, namespacePath);
        normalizeStatements(statement.cleanup, namespacePath);
    }
}

void SemanticAnalyzer::analyze(Program& program) {
    program.classes.erase(
        std::remove_if(program.classes.begin(), program.classes.end(),
                       [](const ClassDeclaration& declaration) {
                           return declaration.builtin;
                       }),
        program.classes.end());
    program.classes.insert(program.classes.begin(), makeBuiltinExceptionClass());
    scopes_.clear();
    symbols_.clear();
    namespaces_.clear();
    namespaceOwners_.clear();
    classes_.clear();
    methodDefinitions_.clear();
    importAliases_.clear();
    currentClass_ = nullptr;
    currentMethod_ = nullptr;
    currentNamespace_.clear();
    currentModule_.clear();
    exceptionHandlerDepth_ = 0;

    for (const auto& import : program.imports) {
        if (import.exportedName.empty()) {
            throw DiagnosticError(import.location,
                                  "import '" + import.moduleName +
                                      "' was not resolved through the module registry");
        }
        auto& aliases = importAliases_[import.importerModule];
        if (!aliases.emplace(import.alias,
                             ImportBinding{import.exportedName, import.moduleName}).second) {
            throw DiagnosticError(import.location,
                                  "duplicate import alias '" + import.alias + "'");
        }
    }
    for (const auto& import : program.imports) {
        const auto conflict = std::find_if(
            program.classes.begin(), program.classes.end(),
            [&import](const ClassDeclaration& declaration) {
                return declaration.moduleName == import.importerModule &&
                       declaration.namespacePath.empty() &&
                       declaration.name == import.alias;
            });
        const auto namespaceConflict = std::find_if(
            program.namespaces.begin(), program.namespaces.end(),
            [&import](const NamespaceDeclaration& declaration) {
                return declaration.moduleName == import.importerModule &&
                       declaration.path.size() == 1 &&
                       declaration.path.front() == import.alias;
            });
        if (conflict != program.classes.end() || namespaceConflict != program.namespaces.end()) {
            throw DiagnosticError(import.location,
                                  "import alias '" + import.alias +
                                      "' conflicts with a local declaration");
        }
    }

    const auto registerNamespacePath = [this](const std::vector<std::string>& path,
                                              const std::string& owner,
                                              const SourceLocation& location) {
        for (std::size_t length = 1; length <= path.size(); ++length) {
            const auto name = qualify(std::vector<std::string>(
                path.begin(), path.begin() + static_cast<std::ptrdiff_t>(length)), "");
            const auto existing = namespaceOwners_.find(name);
            if (existing != namespaceOwners_.end() && existing->second != owner) {
                throw DiagnosticError(location,
                                      "namespace '" + name +
                                          "' cannot be shared across compilation units");
            }
            namespaces_.insert(name);
            namespaceOwners_.emplace(name, owner);
        }
    };
    for (const auto& declaration : program.namespaces) {
        registerNamespacePath(declaration.path, declaration.moduleName, declaration.location);
    }
    for (auto& declaration : program.classes) {
        currentModule_ = declaration.moduleName;
        registerNamespacePath(declaration.namespacePath, declaration.moduleName,
                              declaration.location);
        const auto fullName = qualify(declaration.namespacePath, declaration.name);
        if (!classes_.emplace(fullName, &declaration).second) {
            throw DiagnosticError(declaration.location,
                                  "duplicate class '" + fullName + "'");
        }
    }
    for (const auto& classEntry : classes_) {
        if (namespaces_.find(classEntry.first) != namespaces_.end()) {
            throw DiagnosticError(classEntry.second->location,
                                  "class '" + classEntry.first +
                                      "' conflicts with a namespace of the same name");
        }
    }

    for (auto& declaration : program.classes) {
        currentModule_ = declaration.moduleName;
        declaration.name = qualify(declaration.namespacePath, declaration.name);
        for (std::size_t index = 0; index < declaration.baseClassNames.size(); ++index) {
            declaration.baseClassNames[index] =
                resolveClassName(declaration.baseClassNames[index],
                                 declaration.namespacePath,
                                 declaration.baseLocations[index]);
        }
        if (!declaration.baseClassNames.empty()) {
            declaration.baseClassName = declaration.baseClassNames.front();
        }
        for (auto& field : declaration.fields) {
            normalizeType(field.type, declaration.namespacePath, field.location);
        }
        for (auto& method : declaration.methods) {
            normalizeType(method.returnType, declaration.namespacePath, method.location);
            for (auto& parameter : method.parameters) {
                normalizeType(parameter.type, declaration.namespacePath, parameter.location);
            }
            normalizeStatements(method.body, declaration.namespacePath);
        }
    }
    for (auto& definition : program.outOfLineMethods) {
        currentModule_ = definition.moduleName;
        definition.className = resolveClassName(definition.className,
                                                definition.namespacePath,
                                                definition.location);
        const auto* owner = classes_.at(definition.className);
        if (definition.namespacePath != owner->namespacePath) {
            throw DiagnosticError(definition.location,
                                  "method '" + definition.className + "." +
                                      definition.method.name +
                                      "' must be defined in the same namespace scope as its "
                                      "class declaration");
        }
        if (owner->moduleName != definition.moduleName) {
            throw DiagnosticError(definition.location,
                                  "cannot define methods for class '" +
                                      definition.className +
                                      "' outside its compilation unit");
        }
        normalizeType(definition.method.returnType, owner->namespacePath,
                      definition.method.location);
        for (auto& parameter : definition.method.parameters) {
            normalizeType(parameter.type, owner->namespacePath, parameter.location);
        }
        normalizeStatements(definition.method.body, owner->namespacePath);
    }
    currentModule_.clear();
    normalizeStatements(program.statements, {});

    // Keyed by parameter types as well as name so overloads get distinct
    // out-of-line definitions.
    const auto methodKey = [](const std::string& className, const MethodDeclaration& method) {
        return className + "." + methodSignatureKey(method);
    };
    std::unordered_map<std::string, std::string> externalSymbolSignatures;
    const auto abiCategory = [](const std::string& type) {
        if (type == "int") return std::string("i32");
        if (type == "bool") return std::string("i1");
        if (type == "float") return std::string("double");
        if (type == "unsigned") return std::string("i64");
        if (type == "string") return std::string("ptr,i64");
        if (type == "void") return std::string("void");
        return std::string("ptr");
    };
    for (auto& definition : program.outOfLineMethods) {
        const auto classFound = classes_.find(definition.className);
        if (classFound == classes_.end()) {
            throw DiagnosticError(definition.location,
                                  "out-of-line definition names unknown class '" +
                                      definition.className + "'");
        }
        // Match the declaration by name and parameter types so each overload
        // binds to its own out-of-line definition. Fall back to a name-only
        // match when nothing matches exactly, so a genuine signature
        // mismatch still reports the clearer "does not match" diagnostic.
        auto declaration = std::find_if(
            classFound->second->methods.begin(), classFound->second->methods.end(),
            [&definition](const MethodDeclaration& candidate) {
                return candidate.name == definition.method.name &&
                       sameParameterTypes(candidate, definition.method);
            });
        if (declaration == classFound->second->methods.end()) {
            declaration = std::find_if(
                classFound->second->methods.begin(), classFound->second->methods.end(),
                [&definition](const MethodDeclaration& candidate) {
                    return candidate.name == definition.method.name;
                });
        }
        if (declaration == classFound->second->methods.end()) {
            throw DiagnosticError(definition.location,
                                  "class '" + definition.className +
                                      "' has no in-class declaration for method '" +
                                      definition.method.name + "'");
        }
        if (!declaration->declarationOnly) {
            throw DiagnosticError(definition.location,
                                  "method '" + definition.className + "." +
                                      definition.method.name +
                                      "' already has an in-class definition");
        }
        const auto key = methodKey(definition.className, definition.method);
        const auto readableKey = definition.className + "." + definition.method.name;
        if (!methodDefinitions_.emplace(key, &definition).second) {
            throw DiagnosticError(definition.location,
                                  "duplicate out-of-line definition for method '" + readableKey +
                                      "'");
        }
        if (definition.method.returnType != declaration->returnType ||
            definition.method.parameters.size() != declaration->parameters.size()) {
            throw DiagnosticError(definition.location,
                                  "out-of-line definition signature does not match declaration "
                                  "of '" + readableKey + "'");
        }
        for (std::size_t index = 0; index < declaration->parameters.size(); ++index) {
            if (definition.method.parameters[index].type != declaration->parameters[index].type) {
                throw DiagnosticError(definition.method.parameters[index].location,
                                      "out-of-line definition signature does not match declaration "
                                      "of '" + key + "'");
            }
        }
        if (definition.method.externalBinding) {
            if (definition.method.externalSymbol.empty()) {
                throw DiagnosticError(definition.location,
                                      "native-bound method must name a non-empty C symbol");
            }
            validateExternalMethodType(definition.method.returnType, definition.location, true);
            std::string signature = "ptr;" + abiCategory(definition.method.returnType);
            std::unordered_set<std::string> parameterNames;
            for (const auto& parameter : definition.method.parameters) {
                validateExternalMethodType(parameter.type, parameter.location, false);
                if (!parameterNames.emplace(parameter.name).second) {
                    throw DiagnosticError(parameter.location,
                                          "duplicate parameter '" + parameter.name + "'");
                }
                signature += ";" + abiCategory(parameter.type);
            }
            const auto existing =
                externalSymbolSignatures.find(definition.method.externalSymbol);
            if (existing != externalSymbolSignatures.end() && existing->second != signature) {
                throw DiagnosticError(definition.location,
                                      "external symbol '" +
                                          definition.method.externalSymbol +
                                          "' is reused with an incompatible method signature");
            }
            externalSymbolSignatures.emplace(definition.method.externalSymbol, signature);
        }
    }
    for (auto& declaration : program.classes) {
        currentModule_ = declaration.moduleName;
        for (auto& method : declaration.methods) {
            if (method.declarationOnly &&
                methodDefinitions_.find(methodKey(declaration.name, method)) ==
                    methodDefinitions_.end()) {
                throw DiagnosticError(method.location,
                                      "method '" + declaration.name + "." + method.name +
                                          "' is declared but has no out-of-line definition");
            }
        }
        std::unordered_set<std::string> directBases;
        for (std::size_t index = 0; index < declaration.baseClassNames.size(); ++index) {
            const auto& baseName = declaration.baseClassNames[index];
            if (!directBases.emplace(baseName).second) {
                throw DiagnosticError(declaration.baseLocations[index],
                                      "duplicate base class '" + baseName + "'");
            }
            (void)findClass(baseName, declaration.baseLocations[index]);
        }
        std::unordered_set<std::string> path{declaration.name};
        std::vector<const ClassDeclaration*> pending{&declaration};
        while (!pending.empty()) {
            const auto* ancestor = pending.back();
            pending.pop_back();
            for (std::size_t index = 0; index < ancestor->baseClassNames.size(); ++index) {
                const auto& baseName = ancestor->baseClassNames[index];
                if (!path.emplace(baseName).second) {
                    if (baseName == declaration.name) {
                        throw DiagnosticError(ancestor->baseLocations[index],
                                              "inheritance cycle involving class '" +
                                                  baseName + "'");
                    }
                    continue;
                }
                pending.push_back(findClass(baseName, ancestor->baseLocations[index]));
            }
        }
        for (const auto& field : declaration.fields) {
            validateType(field.type, field.location);
        }
        for (const auto& method : declaration.methods) {
            if (method.destructor &&
                (method.returnType != "void" || !method.parameters.empty())) {
                throw DiagnosticError(method.location,
                                      "destructor must return void and take no parameters");
            }
            validateType(method.returnType, method.location, true);
            for (const auto& parameter : method.parameters) {
                validateType(parameter.type, parameter.location);
            }
        }
        for (std::size_t index = 0; index < declaration.fields.size(); ++index) {
            for (std::size_t other = index + 1; other < declaration.fields.size(); ++other) {
                if (declaration.fields[index].name == declaration.fields[other].name) {
                    throw DiagnosticError(declaration.fields[other].location,
                                          "duplicate field '" + declaration.fields[other].name +
                                              "' in class '" + declaration.name + "'");
                }
            }
        }
        if (!declaration.baseClassName.empty()) {
            const auto hasConstructor = std::any_of(
                declaration.methods.begin(), declaration.methods.end(),
                [](const MethodDeclaration& method) { return method.constructor; });
            if (!hasConstructor) {
                for (std::size_t index = 0; index < declaration.baseClassNames.size(); ++index) {
                    if (declaration.baseVirtual[index]) continue;
                    const auto* base = findClass(declaration.baseClassNames[index],
                                                 declaration.baseLocations[index]);
                    const bool baseHasConstructor = std::any_of(
                        base->methods.begin(), base->methods.end(),
                        [](const MethodDeclaration& method) { return method.constructor; });
                    if (baseHasConstructor) {
                        throw DiagnosticError(declaration.location,
                                              "class '" + declaration.name +
                                                  "' needs an explicit constructor because base '" +
                                                  base->name + "' has one");
                    }
                }
            }
            for (const auto& field : declaration.fields) {
                for (std::size_t index = 0; index < declaration.baseClassNames.size(); ++index) {
                    const auto* base = findClass(declaration.baseClassNames[index],
                                                 declaration.baseLocations[index]);
                    if (countFields(*base, field.name) != 0) {
                        throw DiagnosticError(field.location,
                                              "field '" + field.name +
                                                  "' duplicates an inherited field");
                    }
                }
            }
            for (const auto& method : declaration.methods) {
                if (method.constructor) continue;
                for (const auto& baseName : declaration.baseClassNames) {
                    const auto* base = findClass(baseName, declaration.baseLocation);
                    // Only a same-name, same-parameter-types inherited method is
                    // an override; a different parameter list is a new overload,
                    // which is allowed.
                    const MethodDeclaration* inherited = nullptr;
                    for (const auto* candidate : findOverloads(*base, method.name)) {
                        if (sameParameterTypes(*candidate, method)) {
                            inherited = candidate;
                            break;
                        }
                    }
                    if (inherited == nullptr) continue;
                    if (inherited->returnType != method.returnType) {
                        throw DiagnosticError(method.location,
                                              "override of '" + method.name +
                                                  "' must preserve the inherited method signature");
                    }
                }
            }
        }
        for (std::size_t index = 0; index < declaration.methods.size(); ++index) {
            for (std::size_t other = index + 1; other < declaration.methods.size(); ++other) {
                if (declaration.methods[index].name == declaration.methods[other].name &&
                    sameParameterTypes(declaration.methods[index], declaration.methods[other])) {
                    throw DiagnosticError(declaration.methods[other].location,
                                          "duplicate method '" + declaration.methods[other].name +
                                              "' in class '" + declaration.name + "'");
                }
            }
        }
    }
    for (auto& declaration : program.classes) {
        currentModule_ = declaration.moduleName;
        for (auto& method : declaration.methods) {
            const auto definition = methodDefinitions_.find(methodKey(declaration.name, method));
            analyzeMethod(declaration, definition == methodDefinitions_.end()
                                           ? method
                                           : definition->second->method);
        }
    }
    currentModule_.clear();
    currentClass_ = nullptr;
    currentMethod_ = nullptr;
    currentNamespace_.clear();
    scopes_.emplace_back();
    analyzeStatements(program.statements);
    scopes_.pop_back();
}

void SemanticAnalyzer::validateType(const std::string& type, const SourceLocation& location,
                                   bool allowVoid) const {
    if (type == "any") {
        throw DiagnosticError(
            location,
            "'any' cannot be used as a declared type; collection values may only be tested "
            "with 'is'/'type', printed, compared with null, stored in a collection, or extracted "
            "into a concrete type");
    }
    if (type == "int" || type == "bool" || type == "float" || type == "unsigned" ||
        type == "string" || type == "array" || type == "map" ||
        type == "buffer" || type == "handle" || type == "type" ||
        (allowVoid && type == "void")) {
        return;
    }
    if (classes_.find(type) == classes_.end()) {
        throw DiagnosticError(location, "unknown type or class '" + type + "'");
    }
}

void SemanticAnalyzer::validateExternalMethodType(const std::string& type,
                                                  const SourceLocation& location,
                                                  bool allowVoid) const {
    validateType(type, location, allowVoid);
}

const ClassDeclaration* SemanticAnalyzer::findClass(const std::string& name,
                                                    const SourceLocation& location) const {
    auto found = classes_.find(name);
    if (found == classes_.end()) {
        const auto resolved = resolveClassName(name, currentNamespace_, location);
        found = classes_.find(resolved);
    }
    return found->second;
}

std::size_t SemanticAnalyzer::findSymbolIndex(const std::string& name) const {
    for (auto scope = scopes_.rbegin(); scope != scopes_.rend(); ++scope) {
        const auto found = scope->find(name);
        if (found != scope->end()) {
            return found->second;
        }
    }
    return symbols_.size();
}

std::vector<bool> SemanticAnalyzer::initializationState() const {
    std::vector<bool> state;
    state.reserve(symbols_.size());
    for (const auto& symbol : symbols_) {
        state.push_back(symbol.initialized);
    }
    return state;
}

void SemanticAnalyzer::restoreInitializationState(const std::vector<bool>& state) {
    for (std::size_t index = 0; index < state.size(); ++index) {
        symbols_[index].initialized = state[index];
    }
}

void SemanticAnalyzer::analyzeMethod(const ClassDeclaration& owner,
                                     MethodDeclaration& method) {
    currentNamespace_ = owner.namespacePath;
    const auto savedExceptionHandlerDepth = exceptionHandlerDepth_;
    exceptionHandlerDepth_ = 0;
    if (method.externalBinding) {
        exceptionHandlerDepth_ = savedExceptionHandlerDepth;
        return;
    }
    std::size_t leadingCalls = 0;
    if (method.constructor) {
        const auto virtualBases = virtualBaseNames(owner);
        std::vector<const Statement*> virtualInitializers(virtualBases.size(), nullptr);
        std::vector<std::size_t> requiredBases;
        for (std::size_t index = 0; index < owner.baseClassNames.size(); ++index) {
            if (!owner.baseVirtual[index]) requiredBases.push_back(index);
        }
        std::size_t nextBase = 0;
        std::size_t nextVirtualBase = 0;
        bool directBaseInitializationStarted = false;
        for (const auto& statement : method.body) {
            if (statement.kind != StatementKind::SuperConstructorCall) break;
            if (statement.virtualBaseInitializer) {
                if (directBaseInitializationStarted) {
                    throw DiagnosticError(statement.location,
                                          "virtual base initializers must precede direct base "
                                          "constructor calls");
                }
                const bool hasDerivedClass = std::any_of(
                    classes_.begin(), classes_.end(),
                    [this, &owner](const auto& entry) {
                        return entry.first != owner.name &&
                               isSubclassOf(entry.first, owner.name);
                    });
                if (hasDerivedClass) {
                    throw DiagnosticError(
                        statement.location,
                        "virtual base initializers are only allowed in most-derived classes");
                }
                const auto found = std::find(virtualBases.begin(), virtualBases.end(),
                                             statement.name);
                if (found == virtualBases.end()) {
                    throw DiagnosticError(statement.location,
                                          "super.virtual must name a virtual base of class '" +
                                              owner.name + "'");
                }
                const auto foundIndex = static_cast<std::size_t>(
                    std::distance(virtualBases.begin(), found));
                if (virtualInitializers[foundIndex] != nullptr) {
                    throw DiagnosticError(statement.location,
                                          "virtual base '" + statement.name +
                                              "' is initialized more than once");
                }
                if (foundIndex < nextVirtualBase) {
                    throw DiagnosticError(statement.location,
                                          "virtual base initializers must follow virtual-base "
                                          "construction order");
                }
                virtualInitializers[foundIndex] = &statement;
                nextVirtualBase = foundIndex + 1;
            } else {
                directBaseInitializationStarted = true;
                const auto directBase = std::find(owner.baseClassNames.begin(),
                                                  owner.baseClassNames.end(), statement.name);
                if (directBase != owner.baseClassNames.end() &&
                    owner.baseVirtual[static_cast<std::size_t>(
                        std::distance(owner.baseClassNames.begin(), directBase))]) {
                    throw DiagnosticError(statement.location,
                                          "virtual base constructors must use super.virtual " +
                                              statement.name + "(...)");
                }
                const auto found = std::find_if(
                    requiredBases.begin() + static_cast<std::ptrdiff_t>(nextBase),
                    requiredBases.end(), [&owner, &statement](std::size_t index) {
                        return owner.baseClassNames[index] == statement.name;
                    });
                if (found == requiredBases.end()) {
                    throw DiagnosticError(statement.location,
                                          "base constructors must be initialized once in "
                                          "declared order");
                }
                const auto foundIndex = static_cast<std::size_t>(
                    std::distance(requiredBases.begin(), found));
                for (std::size_t offset = nextBase; offset < foundIndex; ++offset) {
                    const auto baseIndex = requiredBases[offset];
                    const auto* skipped = findClass(owner.baseClassNames[baseIndex],
                                                    owner.baseLocations[baseIndex]);
                    if (std::any_of(skipped->methods.begin(), skipped->methods.end(),
                                    [](const MethodDeclaration& candidate) {
                                        return candidate.constructor;
                                    })) {
                        throw DiagnosticError(method.location,
                                              "derived constructor must initialize base '" +
                                                  skipped->name + "' with super." +
                                                  skipped->name + "(...)");
                    }
                }
                nextBase = foundIndex + 1;
            }
            ++leadingCalls;
        }
        for (std::size_t offset = nextBase; offset < requiredBases.size(); ++offset) {
            const auto index = requiredBases[offset];
            const auto* skipped = findClass(owner.baseClassNames[index],
                                            owner.baseLocations[index]);
            if (std::any_of(skipped->methods.begin(), skipped->methods.end(),
                            [](const MethodDeclaration& candidate) {
                                return candidate.constructor;
                            })) {
                if (index == 0) {
                    throw DiagnosticError(method.location,
                                          "derived constructor must begin with super." +
                                              skipped->name + "(...);");
                }
                throw DiagnosticError(method.location,
                                      "derived constructor must initialize base '" +
                                          skipped->name + "' with super." + skipped->name +
                                          "(...)");
            }
        }
    }
    if (method.returnType != "void" &&
        (method.body.empty() || method.body.back().kind != StatementKind::Return)) {
        throw DiagnosticError(method.location,
                              "non-void prototype methods must end with a direct return statement");
    }
    for (std::size_t index = 0; index < method.body.size(); ++index) {
        const bool directLeadingSuper = method.constructor && index < leadingCalls &&
                                        method.body[index].kind ==
                                            StatementKind::SuperConstructorCall;
        if (containsSuperCall(method.body[index]) && !directLeadingSuper) {
            throw DiagnosticError(method.body[index].location,
                                  "super initializers must be direct leading constructor "
                                  "statements");
        }
        const bool finalDirectReturn = index + 1 == method.body.size() &&
                                       method.body[index].kind == StatementKind::Return;
        if (containsReturn(method.body[index]) && !finalDirectReturn) {
            throw DiagnosticError(method.body[index].location,
                                  "return must be the final direct statement in a prototype method");
        }
    }
    currentClass_ = &owner;
    currentMethod_ = &method;
    scopes_.emplace_back();
    scopes_.emplace_back();
    for (const auto& parameter : method.parameters) {
        if (scopes_.back().find(parameter.name) != scopes_.back().end()) {
            throw DiagnosticError(parameter.location, "duplicate parameter '" + parameter.name + "'");
        }
        const auto index = symbols_.size();
        symbols_.push_back({parameter.name, parameter.type, true, parameter.location});
        scopes_.back().emplace(parameter.name, index);
    }
    analyzeStatements(method.body);
    scopes_.pop_back();
    scopes_.pop_back();
    currentClass_ = nullptr;
    currentMethod_ = nullptr;
    exceptionHandlerDepth_ = savedExceptionHandlerDepth;
}

void SemanticAnalyzer::dumpSymbolTable(std::ostream& output) const {
    output << "Symbols:\n";
    for (const auto& symbol : symbols_) {
        output << "  " << symbol.type << " " << symbol.name << " ("
               << (symbol.initialized ? "initialized" : "uninitialized") << ") at "
               << symbol.location.line << ":" << symbol.location.column << '\n';
    }
}

} // namespace simp
